mapper.select:


    inner join sys_user u on u.user_name = ttaskin.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    ttaskin.del_flag = '0'
    and ttaskin.advance_registration_id = #{advanceRegistrationId}

    and ttaskin.material_id = #{materialId}
    and ttaskin.predict_count = #{predictCount}
    and ttaskin.actual_count = #{actualCount}
    and ttaskin.status = #{status}
    and ttaskin.tray_id = #{trayId}
    and ttaskin.reservoir_id = #{reservoirId}
    and ttaskin.location_id = #{locationId}
    and ttaskin.recommend_location_id = #{recommendLocationId}
    and ttaskin.area_id = #{areaId}
    and ttaskin.batch_code like concat('%', #{batchCode},
        '%')

    and ttaskin.stock_id = #{stockId}
    and ttaskin.wcs_id = #{wcsId}


${params.dataScope}
